(async()=>{try{const r=await fetch('./app-template.html?v=15',{cache:'no-store'});let h=await r.text();const scripts=['./hq-menu-images.js?v=1','./menu-api-bridge.js?v=1','./supabase-menu.js?v=4','./menu-enhancements.js?v=2','./menu-controller.js?v=1','./table-tracking.js?v=1','./order-flow.js?v=1','./menu-state-fix.js?v=1','./ux-refresh-v2.js?v=1'].map(src=>`<script src="${src}"></script>`).join('');h=h.replace('</body>',scripts+'</body>');document.open();document.write(h);document.close();}catch(error){document.body.innerHTML='<div style="color:white;font-family:sans-serif;padding:40px">No se pudo cargar CHIDOLIRO. Recarga la página.</div>';}})();